mapper.select:
select node_id as deviceId,node_type as deviceType,warning_type as repairReason
from tb_early_warning where is_affirm = '2' and warning_type in ('01','02','03')
and area_id = #{areaId}
and stack_id = #{stackId}

mapper.update:
UPDATE tb_early_warning
SET task_id = #{id},is_affirm = #{affirm},principal=#{principal},deal_time = TO_DATE(#{dealTime}, 'SYYYY-MM-DD HH24:MI:SS' )
WHERE is_affirm <> '0' and site_route =  #{siteRoute} AND warning_type = #{warningType}

UPDATE tb_early_warning
SET repair_id = #{id},is_affirm = #{affirm},principal=#{principal}
WHERE is_affirm <> '0' and node_id = #{deviceId}  AND warning_type in('01','02','03')

mapper.select:
select id , warning_grade as warningGrade  , warning_type warningType  , is_affirm affirm from tb_early_warning where node_id =#{nodeId} and is_affirm = 2 or is_affirm = 1

    and warning_type =#{warningType}

limit 1;

select
substring_index(group_concat(warning_type),',',1) AS warningType,
ifnull(count(warning_grade='1' or null),0) AS oneWarningCount,
ifnull(count(warning_grade='2' or null),0) AS twoWarningCount,
ifnull(count(warning_grade='3' or null),0) AS threeWarningCount
from tb_early_warning
where is_affirm = '2'
and warning_type = #{earlyWarningDto.warningType}
 and principal = #{earlyWarningDto.principalName} 
 and warning_time >= #{earlyWarningDto.startTime}
 and warning_time <= #{earlyWarningDto.endTime}

select
warning_type as warningType,
ifnull(count(warning_grade='1' or null),0) AS oneWarningCount,
ifnull(count(warning_grade='2' or null),0) AS twoWarningCount,
ifnull(count(warning_grade='3' or null),0) AS threeWarningCount
from tb_early_warning
where is_affirm = '2' and warning_type not in ('01','02','03')
 and warning_type = #{earlyWarningDto.warningType} 
 and principal = #{earlyWarningDto.principalName} 
 and warning_time >= #{earlyWarningDto.startTime}
 and warning_time <= #{earlyWarningDto.endTime}
group by warning_type order by warning_type

SELECT
node_id as nodeId,warning_type as warningType,warning_grade as warningGrade,warning_val as warningVal,principal as principalName,deal_time as dealTime,
stack_id as stackId,area_id as areaId,task_id as taskId,repair_id as repairId
FROM tb_early_warning
WHERE is_affirm = '0'
and site_route like concat('%',#{earlyWarningDto.pidRoute},'%') 
and warning_type = #{earlyWarningDto.warningType}
and warning_grade = #{earlyWarningDto.warningGrade}
and node_id like concat('%',#{earlyWarningDto.nodeId},'%')
and principal like concat('%',#{earlyWarningDto.principalName},'%')
and deal_time >= #{earlyWarningDto.startTime}
and deal_time <= #{earlyWarningDto.endTime}
ORDER BY site_route

SELECT id FROM tb_early_warning where 1=1
and site_route like concat('%', #{earlyWarningDto.pidRoute}, '%') 
and warning_type = #{earlyWarningDto.warningType}
and principal like concat('%',#{earlyWarningDto.principalName}, '%')
and warning_time >= #{earlyWarningDto.beginTime}
and warning_time <= #{earlyWarningDto.finishTime}
and warning_grade = #{earlyWarningDto.warningGrade}

SELECT count(1) as sumDeal,round(COUNT(1)/#{count},2) * 100 as ratioDeal
FROM tb_early_warning
WHERE is_affirm = '0' and id in  #{id}

select t.site_route from (select site_route from tb_early_warning where is_affirm = '2'
and warning_grade = #{warningGrade}
union select site_route from tb_early_warning where is_affirm = '2' and  warning_type in ('01','02','03')) t group by t.site_route
